  /**
   * Returns a URL for a pay certificate pdf file. This is a absolute link containing
   * both the server address and the access token.
   * @param workerId Worker id for which the certificate should be created.
   * @param calculationIds Calculation ids to include in the certificate.
   * @param inline - If true, the Content-Disposition header is returned with inline parameter.
   */
   public getPayCertificatePdfUrl(workerId: string, calculationIds: string[],  inline = false): string {
    const url = ReportsLogic.getPayCertificatePdfUrl(workerId, calculationIds, inline, this.ajax.getCurrentToken()!);
    return `${this.ajax.getServerAddress()}${url}`;
  }

  /**
   * Validates the pay certificate server side.
   * @param workerId Id of the worker in the certificate.
   * @param calculationIds Calculation ids to include in the certificate.
   * @returns Validation result.
   */
  public validatePayCertificate(workerId: string, calculationIds: string[]): Promise<ApiValidation> {
    let method = `/v03/api/reports/validate/pay-certificate/${encodeURIComponent(workerId)}?`;
    calculationIds.forEach((id) => { method += "calculationIds=" + encodeURIComponent("" + (id ?? "")) + "&"; });
    method = method.replace(/[?&]$/, "");
    return this.ajax.getJSON(method);
  }

  /**
   * Gets an HTML report based on Calculation ID.
   *
   * @param reportType - Type of the report to fetch. See the HtmlReportType enumeration for possible values.
   * @param calculationId - GUID for the calculation
   *
   * @returns A Promise with result HTML.
   */
  public getReportHtmlById(reportType: reportPartial, calculationId: string): Promise<string> {
    let method: string;
    if (!reportType) {
      return Promise.resolve("");
    }
    switch (reportType.toLowerCase()) {
      case "employer":
        method = "/reportpartials/employerCalculation/" + calculationId;
        break;
      case "employerpage2":
        method = "/reportpartials/employerCalculationAdditionalInfo/" + calculationId;
        break;
      case "worker":
        method = "/reportpartials/workerCalculation/" + calculationId;
        break;
      case "workerpage2":
        method = "/reportpartials/workerCalculationAdditionalInfo/" + calculationId;
        break;
      case "payments":
        method = "/reportpartials/paymentCalculation/" + calculationId;
        break;
      default:
        throw new Error("Unknown report partial type: " + reportType);
    }
    return this.ajax.getHTML(this.ajax.getServerAddress() + method);
  }

