  /**
   * Gets a calculation report in PDF format.
   * @param calculations - The calculations to generate the report for
   * @param reportType - The type of report to generate. Can be one of:
   * - "salarySlip" - Salary slip report
   * - "employerReport" - Employer report
   * - "paymentReport" - Payment report
   * - "paymentSummaryReport" - Payment summary report
   * - "accountingReport" - Accounting report
   * - "totalsReport" - Totals report
   * - "rowsReport" - Rows report
   * - "irRows" - IR rows report
   * @param employerLang - The language to use for employer-specific content
   * @param reportLang - The language to use for worker-specific content
   * @returns Promise resolving to an object containing:
   * - data: Blob - The PDF report data
   * - response: any - The full response object
   */
  public getCalculationReport(calculations: Calculation[], reportType: calcReportType, employerLang: Language, reportLang: Language): Promise<{data: Blob, headers: {[key: string]: string}}> {
    // Helper function to make HTTP request and return PDF data
    const makeHttpRequest = (url: string, payload?: any): Promise<{data: Blob, headers: {[key: string]: string}}> => {
     if(payload) {
      return this.ajax.postBlob(url, payload);
     } else {
      return this.ajax.getBlob(url);
     }
    };

    // Handle special report types that use the report server
    if (["paymentSummaryReport", "accountingReport", "totalsReport", "rowsReport"].includes(reportType)) {
      const baseUrl = `${Configs.current.reportServer}/pdf`;
      const commonParams = `disposition=inline&access_token=${this.ajax.getCurrentToken()}`;

      switch (reportType) {
        case ReportType.PaymentSummaryReport: {
          const url = `${baseUrl}?id=&reportType=${encodeURIComponent(reportType)}&template=paymentSummaryReportV2&language=${encodeURIComponent(employerLang)}&${commonParams}`;
          return makeHttpRequest(url, { object: calculations });
        }

        case ReportType.AccountingReport: {
          const url = `${baseUrl}?id=&reportType=${encodeURIComponent(reportType)}&template=accountingReport&language=${encodeURIComponent(employerLang)}&${commonParams}`;
          return this.getAccountingDataForCalculations(calculations).then(accountingData => makeHttpRequest(url, { object: accountingData }));
        }

        case ReportType.TotalsReport: {
          const url = `${baseUrl}?id=&reportType=${encodeURIComponent(reportType)}&template=totalsReport&language=${encodeURIComponent(employerLang)}&${commonParams}`;
          return makeHttpRequest(url, { object: calculations });
        }

        default:
          throw new Error(`Report type ${reportType} is not supported`);
      }
    }

    // Handle standard report types
    const baseUrl = `${this.ajax.getServerAddress()}/v03/api/reports/assure-pdf/${reportType}`;
    const allCalculationsSucceeded = calculations.every(calc => calc?.workflow?.status === CalculationStatus.PaymentSucceeded);

    if (allCalculationsSucceeded) {
      const ids = calculations.map(calc => `ids=${encodeURIComponent(calc.id!)}`).join("&");
      const url = `${baseUrl}?disposition=inline&${ids}&language=${encodeURIComponent(reportLang)}&access_token=${this.ajax.getCurrentToken()}`;
      return makeHttpRequest(url);
    } else {
      const url = `${baseUrl}?language=${encodeURIComponent(reportLang)}&disposition=inline&access_token=${this.ajax.getCurrentToken()}`;
      return makeHttpRequest(url, calculations);
    }
  }
