  /**
   * Gets a blank UserDefinedRow with typed usecase data and usecase specific default data.
   * @param type Type of the usecase for the row.
   */
  public static getBlankUsecaseRow(type: CalculationRowType): UsecaseRow<CalculationRowType, any> {
    const result = {
      rowType: type,
      count: 1,
      accounting: {
        dimensions: [],
      },
      data: {},
    };
    this.getUsecaseLogic(type)?.updateUsecase(result, "today", undefined);
    return result;
  }

