  /**
   * Gets the usecase specific logic for a row type.
   * @param type Row type for which we should return the logic.
   * @returns Usecase logic for the row type.
   */
  public static getUsecaseLogic(type: CalculationRowType): BaseUsecaseLogic {
    switch (type) {
      case CalculationRowType.AbsencePeriod:
        return new AbsencePeriodUsecaseLogic();
      case CalculationRowType.BicycleBenefit:
        return new BicycleBenefitUsecaseLogic();
      case CalculationRowType.Board:
        return new BoardUsecaseLogic();
      case CalculationRowType.CarBenefit:
        return new CarBenefitUsecaseLogic();
      case CalculationRowType.DailyAllowance:
        return new DailyAllowanceUsecaseLogic();
      case CalculationRowType.EmploymentTermination:
        return new EmploymentTerminationUsecaseLogic();
      case CalculationRowType.Expenses:
        return new ExpensesUsecaseLogic();
      case CalculationRowType.Foreclosure:
        return new ForeclosureUsecaseLogic();
      case CalculationRowType.HourlySalaryWithWorkingTimeCompensation:
        return new HourlySalaryWithWorkingTimeCompensationUsecaseLogic();
      case CalculationRowType.IrIncomeType:
        return new IrIncomeTypeUsecaseLogic();
      case CalculationRowType.MealBenefit:
        return new MealBenefitUsecaseLogic();
      case CalculationRowType.MilageOwnCar:
        return new MilageOwnCarUsecaseLogic();
      case CalculationRowType.NonProfitOrg:
        return new NonProfitOrgUsecaseLogic();
      case CalculationRowType.OtherCompensation:
        return new OtherCompensationUsecaseLogic();
      case CalculationRowType.PaidSickLeave:
        return new PaidSickLeaveUsecaseLogic();
      case CalculationRowType.PrepaidExpenses:
        return new ExpensesUsecaseLogic();
      case CalculationRowType.Remuneration:
        return new RemunerationUsecaseLogic();
      case CalculationRowType.SubsidisedCommute:
        return new SubsidisedCommuteUsecaseLogic();
      case CalculationRowType.TotalWorkerPayment:
        return new TotalWorkerPaymentUsecaseLogic();
      case CalculationRowType.Training:
        return new TrainingUsecaseLogic();
      case CalculationRowType.UnionPayment:
        return new UnionPaymentUsecaseLogic();
      case CalculationRowType.WorkingTimeCompensation:
        return new WorkingTimeCompensationUsecaseLogic();
      case CalculationRowType.PayStats:
        return new PayStatsUsecaseLogic();
      case CalculationRowType.TimeRatePay:
        return new TimeRatePayUsecaseLogic();
      case CalculationRowType.TaxAtSource:
        return new TaxAtSourceUsecaseLogic();
      case CalculationRowType.TaxWithholding:
        return new TaxWithholdingUsecaseLogic();
      case CalculationRowType.HolidayBonus:
      case CalculationRowType.HolidaySalary:
      case CalculationRowType.HolidayCompensation:
        return new HolidaysUsecaseLogic();
      default:
        return new DefaultUsecaseLogic();
    }
  }

  /**
   * Returns the grouping filter for a row type.
   * In the typical case each row in the group has the same rowType, type, kind, price, unit and message.
   * Rows in a group can be merged together.
   * @param type Row type for the grouping filter.
   * @param arr Array of rows to group. This is required for some grouping filters especially when there is no reason for grouping but each object should be in its own group.
   * @returns Filter for grouping the rows.
   */
  public static getGroupingFilter(type: CalculationRowType, arr: UserDefinedRow[]):  ((r: UserDefinedRow) => string){
    switch (type) {
      case CalculationRowType.AbsencePeriod:
        return x => this.getRowKey(x,[x.data?.isPaid, x.data?.absenceCustomCode, x.data?.isHolidayAccrual], true) ;
      case CalculationRowType.BicycleBenefit:
        return x => this.getRowId(x, arr);
      case CalculationRowType.Board:
        return x => this.getRowKey(x);
      case CalculationRowType.CarBenefit:
        return x => this.getRowId(x, arr);
      case CalculationRowType.DailyAllowance:
        return x => this.getRowKey(x,[x.data?.country, x.data?.isHalf]) ;
      case CalculationRowType.EmploymentTermination:
        return x => this.getRowKey(x);
      case CalculationRowType.Expenses:
        return x => this.getRowId(x, arr);
      case CalculationRowType.Foreclosure:
        return x => this.getRowId(x, arr);
      case CalculationRowType.HourlySalaryWithWorkingTimeCompensation:
        return x => {
          if ((x.data?.compensationRows?.length ?? 0) != 1 ) {
            return this.getRowId(x, arr);
          }
          const compensationRow = { ...x.data?.compensationRows[0], count: undefined };
          return this.getRowKey(x, [JSON.stringify(compensationRow), x.data?.pricing]);
        };
      case CalculationRowType.IrIncomeType:
        return x => this.getRowKey(x, [x.data?.unit, JSON.stringify(x.data?.irData)]) ;
      case CalculationRowType.MealBenefit:
        return x => this.getRowId(x, arr);
      case CalculationRowType.MilageOwnCar:
        return x => this.getRowKey(x, [x.data?.vehicleType, x.data?.passengerCount, x.data?.additionsAllowed, x.data?.passengersAllowed, JSON.stringify(x.data?.additions)]);
      case CalculationRowType.NonProfitOrg:
        return x => this.getRowKey(x);
      case CalculationRowType.OtherCompensation:
        return x => this.getRowKey(x);
      case CalculationRowType.PaidSickLeave:
        return x => this.getRowKey(x);
      case CalculationRowType.PrepaidExpenses:
        return x => this.getRowId(x, arr);
      case CalculationRowType.Remuneration:
        return x => this.getRowKey(x);
      case CalculationRowType.SubsidisedCommute:
        return x => this.getRowId(x, arr);
      case CalculationRowType.TotalWorkerPayment:
        return x => this.getRowId(x, arr);
      case CalculationRowType.Training:
        return x => this.getRowKey(x);
      case CalculationRowType.UnionPayment:
        return x => this.getRowId(x, arr);
      case CalculationRowType.WorkingTimeCompensation:
        return x => this.getRowKey(x);
      case CalculationRowType.PayStats:
        return x => this.getRowKey(x, arr);
      case CalculationRowType.TaxAtSource:
        return x => this.getRowId(x, arr);
      case CalculationRowType.TaxWithholding:
        return x => this.getRowId(x, arr);
      case CalculationRowType.HolidayBonus:
      case CalculationRowType.HolidaySalary:
      case CalculationRowType.HolidayCompensation:
        return x => this.getRowKey(x);
      default:
        return x => this.getRowKey(x);
    }
  }

  /**
   * Returns usecase logic for a row and calculation.
   * @param row Row that the logic operates on.
   * @param calc Calculation that contains the row (used for date, potentially other things).
   * @param doUpdate If true, will run first updateUsecase on the row.
   */
  public static getUsecaseLogicForCalc(row: UserDefinedRow, calc: Calculation, doUpdate = false): BaseUsecaseLogic {
    row.rowType ??= CalculationRowType.Unknown;
    const logic = RowsUsecaseLogic.getUsecaseLogic(row.rowType);
    if (doUpdate) {
      logic.updateUsecase(row, calc?.workflow?.salaryDate ?? "today", RowUsecaseCalcData.fromCalc(calc));
    }
    return logic;
  }

  /**
   * Returns a validation message for a row or null if none is provided.
   * Does the common validations (price and count) and then runs usecase specific validations.
   * @param row The row that is validated.
   */
  public static getValidation(row: UserDefinedRow): UsecaseValidationMessage | undefined {
    row.rowType ??= CalculationRowType.Unknown;
    return RowsUsecaseLogic.getUsecaseLogic(row.rowType).getValidation(row);
  }

