    if (kind) {
      data.kind = kind;
    }
    const blankRow = RowsUsecaseLogic.getBlankUsecaseRow(rowType);
    if(data) {
      blankRow.data = data;
    }
    this.getUsecaseLogic(rowType)?.updateUsecase(blankRow, "today", undefined);
    return blankRow.data;
