  private static getRowKey(row: UserDefinedRow, additionalFields: any[] = [], excludeMessage: boolean = false): string {
    const items = ["rowKey",row.rowType,row.data?.kind,this.getHarmonizedType(row),row.unit,row.price];
    items.push(...additionalFields);
    if (!excludeMessage) {
      items.push(row.message);
    }
    return items.join("-");
  }
  private static getRowId(row: UserDefinedRow, arr: UserDefinedRow[]): string {
    const items = ["rowId", arr.indexOf(row)];
    return items.join("-");
  }

  private static getHarmonizedType(row: UserDefinedRow): string {
    if (row?.type) {
      return row.type;
    }
    return `/builtIn/${row?.rowType}`;
  }
